PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE, password TEXT NOT NULL, name TEXT NOT NULL, phone TEXT NOT NULL DEFAULT '', role TEXT NOT NULL CHECK(role IN ('customer','master','admin')), active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS categories(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, icon TEXT NOT NULL DEFAULT 'tool', active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS catalog_services(id INTEGER PRIMARY KEY, category TEXT NOT NULL CHECK(category IN ('cleaning','master')), name TEXT NOT NULL UNIQUE, description TEXT NOT NULL, price_label TEXT NOT NULL, icon TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS service_requests(id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL REFERENCES users(id), master_id INTEGER REFERENCES masters(user_id), catalog_service_id INTEGER NOT NULL REFERENCES catalog_services(id), contact_name TEXT NOT NULL, phone TEXT NOT NULL, address TEXT NOT NULL, description TEXT NOT NULL, desired_at TEXT, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','assigned','accepted','in_progress','awaiting_confirmation','completed','cancelled','rejected')), reason TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, request_key TEXT NOT NULL, UNIQUE(customer_id,request_key));
CREATE INDEX IF NOT EXISTS service_requests_master ON service_requests(master_id,status);
CREATE INDEX IF NOT EXISTS service_requests_customer ON service_requests(customer_id);
CREATE TABLE IF NOT EXISTS service_request_messages(id INTEGER PRIMARY KEY, service_request_id INTEGER NOT NULL REFERENCES service_requests(id), master_id INTEGER NOT NULL REFERENCES masters(user_id), author_id INTEGER NOT NULL REFERENCES users(id), body TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS service_request_messages_request ON service_request_messages(service_request_id,id);
CREATE TABLE IF NOT EXISTS service_request_reviews(id INTEGER PRIMARY KEY, service_request_id INTEGER NOT NULL UNIQUE REFERENCES service_requests(id), customer_id INTEGER NOT NULL REFERENCES users(id), master_id INTEGER NOT NULL REFERENCES masters(user_id), rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5), body TEXT NOT NULL, visible INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS service_request_reviews_master ON service_request_reviews(master_id,visible);
CREATE TABLE IF NOT EXISTS masters(user_id INTEGER PRIMARY KEY REFERENCES users(id), title TEXT NOT NULL DEFAULT '', bio TEXT NOT NULL DEFAULT '', city TEXT NOT NULL DEFAULT 'Москва', district TEXT NOT NULL DEFAULT '', experience INTEGER NOT NULL DEFAULT 0 CHECK(experience BETWEEN 0 AND 60), moderation TEXT NOT NULL DEFAULT 'pending' CHECK(moderation IN ('pending','approved','rejected')), reason TEXT NOT NULL DEFAULT '', available INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS services(id INTEGER PRIMARY KEY, master_id INTEGER NOT NULL REFERENCES masters(user_id), category_id INTEGER NOT NULL REFERENCES categories(id), title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', price INTEGER NOT NULL CHECK(price BETWEEN 0 AND 1000000), duration INTEGER NOT NULL CHECK(duration BETWEEN 30 AND 480), active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS availability(id INTEGER PRIMARY KEY, master_id INTEGER NOT NULL REFERENCES masters(user_id), weekday INTEGER NOT NULL CHECK(weekday BETWEEN 0 AND 6), start INTEGER NOT NULL CHECK(start BETWEEN 0 AND 1380), end INTEGER NOT NULL CHECK(end BETWEEN 30 AND 1440), CHECK(start<end));
CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL REFERENCES users(id), master_id INTEGER NOT NULL REFERENCES masters(user_id), service_id INTEGER NOT NULL REFERENCES services(id), service_title TEXT NOT NULL, price INTEGER NOT NULL, duration INTEGER NOT NULL, address TEXT NOT NULL, description TEXT NOT NULL, scheduled_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','in_progress','awaiting_confirmation','completed','cancelled','rejected','disputed')), reason TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, request_key TEXT NOT NULL, UNIQUE(customer_id,request_key));
CREATE INDEX IF NOT EXISTS orders_master_time ON orders(master_id,scheduled_at);
CREATE INDEX IF NOT EXISTS orders_customer ON orders(customer_id);
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(id), actor_id INTEGER NOT NULL REFERENCES users(id), action TEXT NOT NULL, note TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(id), author_id INTEGER NOT NULL REFERENCES users(id), body TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS attachments(id TEXT PRIMARY KEY, order_id INTEGER REFERENCES orders(id), owner_id INTEGER NOT NULL REFERENCES users(id), kind TEXT NOT NULL CHECK(kind IN ('order','portfolio')), caption TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reviews(id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL UNIQUE REFERENCES orders(id), customer_id INTEGER NOT NULL REFERENCES users(id), master_id INTEGER NOT NULL REFERENCES masters(user_id), rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5), body TEXT NOT NULL, visible INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS favorites(user_id INTEGER NOT NULL REFERENCES users(id), master_id INTEGER NOT NULL REFERENCES masters(user_id), PRIMARY KEY(user_id,master_id));
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), order_id INTEGER REFERENCES orders(id), text TEXT NOT NULL, is_read INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tickets(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), subject TEXT NOT NULL, body TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', reply TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY, actor_id INTEGER NOT NULL REFERENCES users(id), action TEXT NOT NULL, target TEXT NOT NULL, created_at TEXT NOT NULL);
PRAGMA user_version=1;
